mapper.select:
SELECT

FROM sys_menu


        AND menu_name LIKE CONCAT('%', #{menuName}, '%')


        AND visible = #{visible}


        AND status = #{status}


ORDER BY parent_id, order_num

SELECT DISTINCT m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.`query`, m.route_name, m.visible, m.status, IFNULL(m.perms,'') AS perms, m.is_frame, m.is_cache, m.menu_type, m.icon, m.order_num, m.create_time FROM sys_menu m LEFT JOIN sys_role_menu rm ON m.menu_id = rm.menu_id LEFT JOIN sys_user_role ur ON rm.role_id = ur.role_id LEFT JOIN sys_role ro ON ur.role_id = ro.role_id LEFT JOIN sys_user u ON ur.user_id = u.user_id WHERE u.user_id = #{userId}
AND m.menu_name LIKE CONCAT('%', #{menuName}, '%')
AND m.visible = #{visible}
AND m.status = #{status}
ORDER BY m.parent_id, m.order_num

SELECT

FROM sys_menu
WHERE menu_name = #{menuName} AND parent_id = #{parentId}

    AND menu_id != #{excludeMenuId}

LIMIT 1
